    10→/**
    11→ * An exporter for OBJ.
    12→ *
    13→ * `OBJExporter` is not able to export material data into MTL files so only geometry data are supported.
    14→ *
    15→ * ```js
    16→ * const exporter = new OBJExporter();
    17→ * const data = exporter.parse( scene );
    18→ * ```
    19→ */
    20→class OBJExporter {
    21→
    22→	/**
    23→	 * Parses the given 3D object and generates the OBJ output.
    24→	 *
    25→	 * If the 3D object is composed of multiple children and geometry, they are merged into a single mesh in the file.
    26→	 *
    27→	 * @param {Object3D} object - The 3D object to export.
    28→	 * @return {string} The exported OBJ.
    29→	 */
    30→	parse( object ) {
    31→
    32→		let output = '';
    33→
    34→		let indexVertex = 0;
    35→		let indexVertexUvs = 0;
    36→		let indexNormals = 0;
    37→
    38→		const vertex = new Vector3();
    39→		const color = new Color();
    40→		const normal = new Vector3();
    41→		const uv = new Vector2();
    42→
    43→		const face = [];
    44→
    45→		function parseMesh( mesh ) {
    46→
    47→			let nbVertex = 0;
    48→			let nbNormals = 0;
    49→			let nbVertexUvs = 0;
    50→
    51→			const geometry = mesh.geometry;
    52→
    53→			const normalMatrixWorld = new Matrix3();
    54→
    55→			// shortcuts
    56→			const vertices = geometry.getAttribute( 'position' );
    57→			const normals = geometry.getAttribute( 'normal' );
    58→			const uvs = geometry.getAttribute( 'uv' );
    59→			const indices = geometry.getIndex();
    60→
    61→			// name of the mesh object
    62→			output += 'o ' + mesh.name + '\n';
    63→
    64→			// name of the mesh material
    65→			if ( mesh.material && mesh.material.name ) {
    66→
    67→				output += 'usemtl ' + mesh.material.name + '\n';
    68→
    69→			}
    70→
    71→			// vertices
    72→
    73→			if ( vertices !== undefined ) {
    74→
    75→				for ( let i = 0, l = vertices.count; i < l; i ++, nbVertex ++ ) {
    76→
    77→					vertex.fromBufferAttribute( vertices, i );
    78→
    79→					// transform the vertex to world space
    80→					vertex.applyMatrix4( mesh.matrixWorld );
    81→
    82→					// transform the vertex to export format
    83→					output += 'v ' + vertex.x + ' ' + vertex.y + ' ' + vertex.z + '\n';
    84→
    85→				}
    86→
    87→			}
    88→
    89→			// uvs
    90→
    91→			if ( uvs !== undefined ) {
    92→
    93→				for ( let i = 0, l = uvs.count; i < l; i ++, nbVertexUvs ++ ) {
    94→
    95→					uv.fromBufferAttribute( uvs, i );
    96→
    97→					// transform the uv to export format
    98→					output += 'vt ' + uv.x + ' ' + uv.y + '\n';
    99→
   100→				}
   101→
   102→			}
   103→
   104→			// normals
   105→
   106→			if ( normals !== undefined ) {
   107→
   108→				normalMatrixWorld.getNormalMatrix( mesh.matrixWorld );
   109→
   110→				for ( let i = 0, l = normals.count; i < l; i ++, nbNormals ++ ) {
   111→
   112→					normal.fromBufferAttribute( normals, i );
   113→
   114→					// transform the normal to world space
   115→					normal.applyMatrix3( normalMatrixWorld ).normalize();
   116→
   117→					// transform the normal to export format
   118→					output += 'vn ' + normal.x + ' ' + normal.y + ' ' + normal.z + '\n';
   119→
   120→				}
   121→
   122→			}
   123→
   124→			// faces
   125→
   126→			if ( indices !== null ) {
   127→
   128→				for ( let i = 0, l = indices.count; i < l; i += 3 ) {
   129→
   130→					for ( let m = 0; m < 3; m ++ ) {
   131→
   132→						const j = indices.getX( i + m ) + 1;
   133→
   134→						face[ m ] = ( indexVertex + j ) + ( normals || uvs ? '/' + ( uvs ? ( indexVertexUvs + j ) : '' ) + ( normals ? '/' + ( indexNormals + j ) : '' ) : '' );
   135→
   136→					}
   137→
   138→					// transform the face to export format
   139→					output += 'f ' + face.join( ' ' ) + '\n';
   140→
   141→				}
   142→
   143→			} else {
   144→
   145→				for ( let i = 0, l = vertices.count; i < l; i += 3 ) {
   146→
   147→					for ( let m = 0; m < 3; m ++ ) {
   148→
   149→						const j = i + m + 1;
   150→
   151→						face[ m ] = ( indexVertex + j ) + ( normals || uvs ? '/' + ( uvs ? ( indexVertexUvs + j ) : '' ) + ( normals ? '/' + ( indexNormals + j ) : '' ) : '' );
   152→
   153→					}
   154→
   155→					// transform the face to export format
   156→					output += 'f ' + face.join( ' ' ) + '\n';
   157→
   158→				}
   159→
   160→			}
   161→
   162→			// update index
