import * as THREE from 'three';
import { OBJExporter } from 'three/examples/jsm/exporters/OBJExporter.js';
import { createScene } from './data/object.js';
import fs from 'fs';
import path from 'path';

// Create the scene from the source file
const root = createScene();

// Apply -90 degree X-rotation to convert from Three.js Y-up to Blender Z-up
const exportRoot = new THREE.Group();
exportRoot.rotation.x = -Math.PI / 2;
exportRoot.add(root);

// Update all world matrices before processing
exportRoot.updateMatrixWorld(true);

// Convert InstancedMesh objects to regular Meshes so OBJExporter can handle them.
// OBJExporter.parse() only processes children with `isMesh === true` using
// mesh.matrixWorld, but InstancedMesh instances store per-instance transforms
// in instanceMatrix which the exporter ignores.
function convertInstancedMeshes(object) {
  const replacements = [];

  object.traverse((child) => {
    if (child.isInstancedMesh) {
      replacements.push(child);
    }
  });

  for (const instMesh of replacements) {
    const parent = instMesh.parent;
    const count = instMesh.count;
    const geometry = instMesh.geometry;
    const material = instMesh.material;

    const group = new THREE.Group();
    group.name = instMesh.name;

    for (let i = 0; i < count; i++) {
      const matrix = new THREE.Matrix4();
      instMesh.getMatrixAt(i, matrix);

      const mesh = new THREE.Mesh(geometry.clone(), material);
      mesh.name = `${instMesh.name}_${i}`;

      // Apply the instance matrix to the geometry directly won't work well
      // because OBJExporter uses matrixWorld. Instead, decompose the instance
      // matrix into position/rotation/scale and apply to the mesh.
      mesh.applyMatrix4(matrix);

      group.add(mesh);
    }

    // Copy the instanced mesh's own transform to the group
    group.position.copy(instMesh.position);
    group.rotation.copy(instMesh.rotation);
    group.scale.copy(instMesh.scale);

    parent.remove(instMesh);
    parent.add(group);
  }

  // Recompute all world matrices after the replacement
  object.updateMatrixWorld(true);
}

convertInstancedMeshes(exportRoot);

// The OBJExporter uses matrixWorld to transform vertices.
// When there's a negative determinant (odd number of negative scale axes),
// the face winding order gets flipped. We need to detect this and reverse
// the index order for those meshes so the OBJ normals face correctly.
function fixNegativeScaleMeshes(object) {
  object.traverse((child) => {
    if (child.isMesh) {
      const det = child.matrixWorld.determinant();
      if (det < 0) {
        const geometry = child.geometry;
        // Ensure we don't modify shared geometry
        child.geometry = geometry.clone();
        const index = child.geometry.getIndex();
        if (index) {
          const arr = index.array.slice();
          for (let i = 0; i < arr.length; i += 3) {
            const tmp = arr[i];
            arr[i] = arr[i + 2];
            arr[i + 2] = tmp;
          }
          child.geometry.setIndex(new THREE.BufferAttribute(arr, 1));
        }
      }
    }
  });
}

fixNegativeScaleMeshes(exportRoot);

// Export to OBJ
const exporter = new OBJExporter();
const objData = exporter.parse(exportRoot);

// Ensure output directory exists
const outputDir = '/root/output';
if (!fs.existsSync(outputDir)) {
  fs.mkdirSync(outputDir, { recursive: true });
}

const outputPath = path.join(outputDir, 'object.obj');
fs.writeFileSync(outputPath, objData);

console.log(`OBJ file exported to: ${outputPath}`);
console.log(`File size: ${(fs.statSync(outputPath).size / 1024).toFixed(1)} KB`);

